<template>
  <main class="notice-page">
    <div v-if="!active" class="notice-card">
      <div class="notice-section-head"><div><h2>检查通报</h2><p>上传微信群截图，逐项核对后导出带图片的 Excel。</p></div><button class="primary" @click="createReport" :disabled="busy">新建通报</button></div>

      <form class="notice-search" @submit.prevent="reportPage=1;refreshList()"><label>标题<input v-model="reportFilters.title" placeholder="搜索通报标题"></label><label>更新起始日<input type="date" v-model="reportFilters.from"></label><label>更新截止日<input type="date" v-model="reportFilters.to"></label><label class="archive-filter"><input type="checkbox" :checked="reportFilters.includeArchived==='1'" @change="reportFilters.includeArchived=$event.target.checked?'1':'0'">包含归档</label><button type="submit">查询</button></form>
      <div class="notice-list"><button v-for="report in reports" :key="report.id" @click="openReport(report.id)"><b>{{report.title}}</b><span>{{workshops[report.workshopCode]}} · {{report.sourceCount}} 张截图 · {{report.updatedAt}}</span><strong>继续整理 →</strong></button><p v-if="!reports.length">还没有检查通报。</p></div>
      <div class="notice-pages"><span>共 {{reportTotal}} 份 · 第 {{reportPage}} 页</span><button @click="reportPage--;refreshList()" :disabled="reportPage<=1">上一页</button><button @click="reportPage++;refreshList()" :disabled="reportPage*20>=reportTotal">下一页</button></div>
    </div>
    <template v-else>
      <div class="notice-card notice-toolbar"><button @click="closeReport" :disabled="busy">← 返回通报列表</button><div><strong>{{active.header.title}}</strong><small>{{saveStatus}} · 待核对 {{pendingIssueCount}} 项</small></div><button @click="jumpToPending" :disabled="!pendingIssueCount">下一条待核对</button><button @click="save" :disabled="busy||!dirty">保存修改</button><button class="primary" @click="download" :disabled="busy">导出 Excel</button></div>
      <p class="notice-info">截图和已保存条目保存在服务器。显示“未保存修改”时，刷新或离开页面会丢失这些修改；上传新截图和识别前会先保存。</p>
      <div class="notice-editor" :inert="busy">
      <details class="notice-card notice-meta"><summary>通报信息 <small>标题、时间、范围、人员与项目</small></summary><div class="notice-header-grid"><label>标题<input v-model="active.header.title" maxlength="160"></label><label>检查时间<input v-model="active.header.checkTime" placeholder="例如：2026/9/14—9/20"></label><label>检查范围<input v-model="active.header.checkScope"></label><label>检查人员<input v-model="active.header.inspectors"></label><label>检查项目<input v-model="active.header.checkItems"></label></div></details>
      <div class="notice-workspace">
      <section class="notice-card"><div class="notice-section-head"><div><h2>原始截图</h2><p>上传后自动尝试识别；原截图始终保留，失败时只重试失败截图。</p></div><label class="file-button">追加截图<input ref="fileInput" type="file" accept="image/png,image/jpeg" multiple @change="uploadFiles" :disabled="busy"></label></div>
        <p v-if="progress" role="status" class="progress">{{progress}} <button v-if="failedFiles.length&&!busy" @click="retryFailedUploads">重试失败的 {{failedFiles.length}} 张</button></p><p v-if="capability" class="capability" :class="{unavailable:!capability.enabled}">{{capability.reason}}</p>
        <div class="source-actions"><span>每次最多上传 8 张，单张不超过 6MB；每份通报最多 40 张。</span><button @click="analyzePending" :disabled="busy||!capability?.enabled||!pendingSources.length">识别待处理截图（{{pendingSources.length}}）</button></div>
        <div class="sources"><article v-for="source in active.sources.filter(row=>!row.reviewed)" :id="`source-${source.id}`" :key="source.id" class="source-card"><button class="source-thumb" @click="viewSource=source" :aria-label="`查看原始截图 ${source.id}`"><InspectionImage :notice-id="active.id" :source-id="source.id" alt="原始群聊截图"/></button><div class="source-detail"><b>截图 {{source.id}}</b><small>{{source.filename}}</small><span :class="['source-status',source.status]">{{sourceStatus(source)}}</span><p v-if="source.duplicate_of" class="warning">与截图 {{source.duplicate_of}} 完全相同，已保留待核对。</p><p v-if="source.error_message" class="warning">{{source.error_message}}</p><label class="review-toggle"><input type="checkbox" :checked="Boolean(source.reviewed)" @change="reviewSource(source,$event.target.checked)" :disabled="busy">已核对该原截图</label></div><button v-if="source.status==='failed'&&capability?.enabled" @click="analyze([source.id])" :disabled="busy">重试</button></article><p v-if="!active.sources.length">先添加群聊截图。模型不可用时也可以手工录入问题和配图。</p></div>
        <details v-if="active.sources.some(row=>row.reviewed)" class="reviewed-sources"><summary>已核对截图（{{active.sources.filter(row=>row.reviewed).length}}）</summary><div v-for="source in active.sources.filter(row=>row.reviewed)" :key="source.id" class="reviewed-source"><button @click="viewSource=source">查看截图 {{source.id}}</button><span>{{source.filename}}</span><button @click="reviewSource(source,false)">撤销核对</button></div></details>
      </section>
      <section class="notice-card"><div class="notice-section-head"><div><h2>问题核对</h2><p>按聊天顺序核对问题描述和现场照片；识别结果都需人工确认，整改意见留空供人工填写。</p></div><div class="issue-tools"><button @click="addIssue">＋ 手工新增</button><button @click="mergeSelected" :disabled="selectedIssueIds.length<2">合并选中</button><button v-if="mergeUndo" @click="undoMerge">撤销上次合并</button></div></div>
        <div v-if="active.issues.length" class="issue-navigation"><label>跳转问题<select v-model="issueJump" @change="scrollIssue(issueJump)"><option v-for="(row,index) in active.issues" :key="row.id" :value="row.id">{{index+1}} · {{row.problem?.slice(0,18)||'待补说明'}} {{row.reviewStatus==='confirmed'?'✓':'待核对'}}</option></select></label></div>
        <div class="issues"><article v-for="(issue,index) in active.issues" :id="`issue-${issue.id}`" :key="issue.id" class="issue-card"><div class="issue-top"><label><input type="checkbox" :value="issue.id" v-model="selectedIssueIds"> 合并选择</label><strong>问题 {{index+1}}</strong><span :class="['review-badge',issue.reviewStatus]">{{issue.reviewStatus==='confirmed'?'人工已确认':'待核对'}}</span><span v-if="issue.origin==='ai'" class="ai-label">AI 草稿</span><div class="issue-top-actions"><button @click="moveIssue(index,-1)" :disabled="index===0">上移</button><button @click="moveIssue(index,1)" :disabled="index===active.issues.length-1">下移</button><button @click="splitIssue(index)">拆分</button><button @click="deleteIssue(index)">删除</button></div></div>
          <p v-if="issue.duplicateHint" class="warning">{{issue.duplicateHint}}</p><p v-if="issue.missingInfo" class="warning">缺失信息：{{issue.missingInfo}}</p><p v-if="issue.pairingReason" class="pairing">配对依据：{{issue.pairingReason}}</p><p v-if="issue.rawText" class="raw-text">截图原文：{{issue.rawText}}</p>
          <label class="issue-problem">问题描述<textarea v-model="issue.problem" rows="3" @input="invalidateIssue(issue)"></textarea></label>
          <div class="issue-photos"><div class="photo-title"><b>问题图片（{{issue.photos.length}}）</b><span>每条最多 8 张；整改图片第一版留空</span></div><div class="photo-list"><div v-for="(photo,photoIndex) in issue.photos" :key="`${photo.sourceId}-${photoIndex}`" class="photo-item"><InspectionImage :notice-id="active.id" :source-id="photo.sourceId" :rect="photo.rect" alt="裁切的现场问题照片"/><small>截图 {{photo.sourceId}}</small><div><button @click="editCrop(index,photoIndex)">调整裁切</button><button @click="removePhoto(index,photoIndex)">取消配图</button></div><select aria-label="把照片关联到其他问题" @change="movePhoto(index,photoIndex,$event.target.value);$event.target.value=''" :value="''"><option value="">移至其他问题…</option><option v-for="(target,otherIndex) in active.issues" :key="target.id" :value="otherIndex" :disabled="otherIndex===index">问题 {{otherIndex+1}}</option></select></div><p v-if="!issue.photos.length">暂无配图，可从原截图选择并调整裁切。</p></div><div class="attach-actions"><select v-model="attachSource[issue.id]" aria-label="选择原截图"><option value="">选择原截图</option><option v-for="source in active.sources" :key="source.id" :value="String(source.id)">截图 {{source.id}} · {{source.filename}}</option></select><button @click="startAttach(index)" :disabled="!attachSource[issue.id]">从截图选照片</button></div></div>
          <details class="issue-extra"><summary>补充工段、类别、整改意见等（人工填写）</summary><div class="issue-fields"><label>工段<input v-model="issue.segment" @input="invalidateIssue(issue)"></label><label>位置<input v-model="issue.location" @input="invalidateIssue(issue)"></label><label>设备编号<input v-model="issue.equipment" @input="invalidateIssue(issue)"></label><label>类别<input v-model="issue.category" @input="invalidateIssue(issue)"></label><label class="wide">整改意见<textarea v-model="issue.rectification" rows="2" placeholder="由核对人员填写" @input="invalidateIssue(issue)"></textarea></label><label class="wide">备注<textarea v-model="issue.remarks" rows="2" placeholder="只填写人工确认的信息" @input="invalidateIssue(issue)"></textarea></label></div></details>
          <label class="confirm-line"><input type="checkbox" :checked="issue.reviewStatus==='confirmed'" @change="confirmIssue(issue,$event.target.checked)">我已核对这条问题描述和配图</label>
        </article><p v-if="!active.issues.length">暂时没有问题。可以手工新增；识图成功后也会追加待核对条目，不覆盖已修改的内容。</p></div>
      </section>
      </div>
      <details class="notice-card notice-history"><summary>修改记录、恢复与归档</summary><div class="history-tools"><button @click="loadEvents">查看最近修改记录</button><span v-if="storage">当前可见范围原图 {{formatBytes(storage.source_bytes)}} / {{storage.sources}} 张；原图到期不会自动删除</span></div><div v-if="events.length" class="history-list"><div v-for="entry in events" :key="entry.id"><span>{{entry.created_at}} · {{eventNames[entry.event_type]||entry.event_type}} · 第 {{entry.revision}} 版</span><button v-if="['edited','analyzed','restored'].includes(entry.event_type)" @click="restoreEvent(entry)">恢复到本次修改前</button></div></div><div class="lifecycle-fields"><label>原图计划保留至<input type="date" v-model="retentionDraft"></label><label><input type="checkbox" v-model="archiveDraft">归档本通报</label><button @click="saveLifecycle" :disabled="busy">保存归档设置</button></div><p>归档只从常用列表收起，原图及审计记录仍保留且受车间权限保护；到期清理需经单独备份与审批。</p></details>
      </div>
    </template>
    <div v-if="viewSource" class="modal-backdrop" @click.self="viewSource=null"><section ref="sourceDialog" tabindex="-1" class="image-modal" role="dialog" aria-modal="true" aria-label="原始群聊截图" @keydown="modalKeys($event,'source')"><header><b>原始截图 {{viewSource.id}}</b><button @click="viewSource=null" aria-label="关闭">✕</button></header><InspectionImage :notice-id="active.id" :source-id="viewSource.id" alt="完整原始群聊截图"/></section></div>
    <div v-if="cropEditor" class="modal-backdrop" @click.self="cropEditor=null"><section ref="cropDialog" tabindex="-1" class="crop-modal" role="dialog" aria-modal="true" aria-label="调整现场照片裁切" @keydown="modalKeys($event,'crop')"><header><b>截图 {{cropEditor.sourceId}} · 调整照片范围</b><button @click="cropEditor=null" aria-label="关闭">✕</button></header><p>上下滚动查看整张截图；点击现场照片定位裁切框，拖动框或滑块微调。尽量排除头像和聊天文字。</p><label class="crop-zoom">预览放大 {{Math.round(cropZoom*100)}}% <input type="range" min="1" max="2.5" step="0.1" v-model.number="cropZoom"></label><div class="crop-viewport"><div ref="cropStage" class="crop-stage" :style="{...cropStageStyle,width:`${cropZoom*100}%`}" @click="positionCrop"><InspectionImage :notice-id="active.id" :source-id="cropEditor.sourceId" alt="待裁切原截图"/><div class="crop-box" :style="cropBoxStyle" @click.stop @pointerdown="startCropDrag"></div></div></div><div class="crop-sliders"><label v-for="key in ['x','y','w','h']" :key="key">{{cropLabels[key]}} {{Math.round(cropEditor.rect[key]*100)}}%<input type="range" min="0" max="100" step="1" :value="Math.round(cropEditor.rect[key]*100)" @input="setCropField(key,Number($event.target.value)/100)"></label></div><footer><button @click="cropEditor=null">取消</button><button class="primary" @click="applyCrop">确认裁切</button></footer></section></div>
  </main>
</template>
<script setup>
import {ref,computed,watch,nextTick,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {getUser} from '../auth'
import {inspection} from '../api/inspection'
import InspectionImage from '../components/InspectionImage.vue'
import {mergeIssues} from '../inspection-merge.mjs'
const workshops={raw_grain:'原粮车间',qu_making:'制曲车间',brewing:'酿酒车间'}
const cropLabels={x:'左边距',y:'上边距',w:'宽度',h:'高度'}
const route=useRoute(),router=useRouter()
const newWorkshop=ref('raw_grain'),reports=ref([]),active=ref(null),capability=ref(null),busy=ref(false),progress=ref(''),failedFiles=ref([]),savedSnapshot=ref(''),viewSource=ref(null),cropEditor=ref(null),cropStage=ref(null),selectedIssueIds=ref([]),attachSource=ref({}),mergeUndo=ref(null)
const reportFilters=ref({title:'',from:'',to:'',includeArchived:'0'}),reportPage=ref(1),reportTotal=ref(0),issueJump=ref(''),pendingCursor=ref(-1)
const sourceDialog=ref(null),cropDialog=ref(null),cropZoom=ref(1)
const events=ref([]),storage=ref(null),retentionDraft=ref(''),archiveDraft=ref(false)
const eventNames={created:'新建通报',edited:'修改或确认条目',sources_added:'追加原图',source_reviewed:'核对原图',analyzed:'AI 识别追加',exported:'导出 Excel',restored:'恢复历史内容',lifecycle:'归档设置'}
const formatBytes=value=>`${(Number(value||0)/1024/1024).toFixed(1)} MB`
let modalOpener=null
function modalKeys(event,type){if(event.key==='Escape'){event.preventDefault();if(type==='source')viewSource.value=null;else cropEditor.value=null;return}if(event.key!=='Tab')return;const dialog=type==='source'?sourceDialog.value:cropDialog.value;const controls=[...dialog.querySelectorAll('button,input,select,textarea,[tabindex]')].filter(item=>!item.disabled&&item.tabIndex>=0);if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
watch([viewSource,cropEditor],async([source,crop],[oldSource,oldCrop])=>{if((source&&!oldSource)||(crop&&!oldCrop)){modalOpener=document.activeElement;if(crop)cropZoom.value=1;await nextTick();(crop?cropDialog.value:sourceDialog.value)?.querySelector('button')?.focus()}else if(!source&&!crop&&(oldSource||oldCrop)){await nextTick();modalOpener?.focus?.();modalOpener=null}})
const snapshot=()=>JSON.stringify({header:active.value?.header,issues:active.value?.issues})
const dirty=computed(()=>Boolean(active.value)&&snapshot()!==savedSnapshot.value)
const saveStatus=computed(()=>busy.value?'正在处理…':dirty.value?'未保存修改':'已保存到服务器')
const pendingSources=computed(()=>active.value?.sources.filter(source=>['pending','failed'].includes(source.status))||[])
const pendingIssueCount=computed(()=>active.value?.issues.filter(issue=>issue.reviewStatus!=='confirmed').length||0)
const cropBoxStyle=computed(()=>cropEditor.value?{left:`${cropEditor.value.rect.x*100}%`,top:`${cropEditor.value.rect.y*100}%`,width:`${cropEditor.value.rect.w*100}%`,height:`${cropEditor.value.rect.h*100}%`}:{})
const cropStageStyle=computed(()=>{const source=active.value?.sources.find(item=>Number(item.id)===Number(cropEditor.value?.sourceId));return source?{'--ratio':String(source.width/source.height),aspectRatio:`${source.width}/${source.height}`}:{}})
function sourceStatus(source){return {pending:'待识别',processing:'识别中',done:'已识别',failed:'识别失败'}[source.status]||source.status}
async function init(){try{const cap=await inspection.get('/capability');capability.value=cap.data;await refreshList();if(route.query.id)await openReport(route.query.id,false);inspection.get('/storage').then(space=>storage.value=space.data).catch(()=>{})}catch{}}
async function loadReport(id,expectedId=null){const response=await inspection.get(`/reports/${id}`);if(expectedId!==null&&String(active.value?.id)!==String(expectedId))return false;active.value=response.data;savedSnapshot.value=snapshot();selectedIssueIds.value=[];mergeUndo.value=null;events.value=[];retentionDraft.value=String(active.value.retentionUntil||'').slice(0,10);archiveDraft.value=active.value.archived;return true}
async function loadEvents(){if(!active.value)return;const response=await inspection.get(`/reports/${active.value.id}/events`);events.value=response.data.items}
async function restoreEvent(entry){if(!await save())return;try{await ElMessageBox.confirm(`恢复到事件 ${entry.id} 修改前的通报内容？当前内容会保留在审计快照中，原截图不会删除。`,'恢复历史',{type:'warning',confirmButtonText:'恢复',cancelButtonText:'取消'})}catch{return}const reportId=active.value.id;busy.value=true;try{await inspection.post(`/reports/${reportId}/restore/${entry.id}`,{revision:active.value.revision});await loadReport(reportId,reportId);ElMessage.success('历史内容已恢复；请重新核对确认状态')}finally{busy.value=false}}
async function saveLifecycle(){if(!await save())return;const reportId=active.value.id;busy.value=true;try{await inspection.patch(`/reports/${reportId}/lifecycle`,{revision:active.value.revision,retentionUntil:retentionDraft.value||null,archived:archiveDraft.value});await loadReport(reportId,reportId);ElMessage.success('归档与保留信息已保存')}finally{busy.value=false}}
function scrollIssue(id){document.getElementById(`issue-${id}`)?.scrollIntoView({behavior:'smooth',block:'start'})}
function jumpToPending(){const issues=active.value?.issues||[];if(!issues.length)return;for(let offset=1;offset<=issues.length;offset++){const index=(pendingCursor.value+offset)%issues.length;if(issues[index].reviewStatus!=='confirmed'){pendingCursor.value=index;issueJump.value=issues[index].id;scrollIssue(issueJump.value);return}}}
async function openReport(id,navigate=true){await loadReport(id);if(navigate)await router.replace({path:'/inspection-notices',query:{id}})}
async function closeReport(){if(busy.value)return;if(dirty.value){try{await ElMessageBox.confirm('当前修改还没有保存，离开后会丢失。','未保存修改',{confirmButtonText:'离开',cancelButtonText:'继续编辑',type:'warning'})}catch{return}}active.value=null;await router.replace({path:'/inspection-notices',query:{}});await refreshList()}
async function refreshList(){const response=await inspection.get('/reports',{params:{page:reportPage.value,pageSize:20,...reportFilters.value}});reports.value=response.data.items;reportTotal.value=response.data.total}
async function createReport(){busy.value=true;try{const response=await inspection.post('/reports',{workshopCode:newWorkshop.value,header:{title:`${workshops[newWorkshop.value]||'车间'}综合检查通报`}});await openReport(response.data.id)}finally{busy.value=false}}
async function save(){if(!active.value||!dirty.value)return true;busy.value=true;const reportId=active.value.id,payload=snapshot();try{const response=await inspection.patch(`/reports/${reportId}`,{revision:active.value.revision,...JSON.parse(payload)});if(active.value?.id!==reportId)return false;active.value.revision=response.data.revision;active.value.issues=response.data.issues;savedSnapshot.value=snapshot();if(JSON.stringify(JSON.parse(payload).issues)!==JSON.stringify(response.data.issues))ElMessage.warning('内容变化后已撤销旧确认，请重新核对对应条目');else ElMessage.success('修改已保存');return true}catch{return false}finally{busy.value=false}}
async function uploadFiles(event){const files=[...event.target.files||[]];event.target.value='';await uploadSelected(files,false)}
async function retryFailedUploads(){const files=[...failedFiles.value];failedFiles.value=[];await uploadSelected(files,true)}
async function uploadSelected(files,retry){if(!files.length)return;if(files.some(file=>!['image/png','image/jpeg'].includes(file.type)||file.size>6*1024*1024)){ElMessage.error('只支持 JPG/PNG，单张不超过 6MB');return}if(!retry&&active.value.sources.length+files.length>40){ElMessage.error('每份通报最多 40 张截图');return}if(!await save())return;const added=[];busy.value=true;try{for(let offset=0;offset<files.length;offset+=8){const group=files.slice(offset,offset+8),data=new FormData();group.forEach(file=>data.append('screenshots',file));if(retry)data.append('retry','1');progress.value=`正在上传 ${offset+1}—${offset+group.length} / ${files.length} 张`;try{const response=await inspection.post(`/reports/${active.value.id}/sources`,data,{onUploadProgress:e=>{progress.value=`正在上传 ${offset+1}—${offset+group.length} / ${files.length} 张 · ${Math.round(100*e.loaded/(e.total||1))}%`}});added.push(...(response.data.added||[]).map(item=>item.id));await loadReport(active.value.id)}catch{failedFiles.value=files.slice(offset);progress.value='部分截图上传失败，已成功的截图仍保留；可重试失败部分。';break}}}finally{busy.value=false}if(capability.value?.enabled&&added.length){for(let offset=0;offset<added.length;offset+=4)await analyze(added.slice(offset,offset+4))}else if(added.length)progress.value=`截图已保存，但自动识别不可用：${capability.value?.reason||'请检查识图配置'}可手工录入并关联照片。`}
async function analyzePending(){const ids=pendingSources.value.map(source=>source.id);for(let offset=0;offset<ids.length;offset+=4){const group=ids.slice(offset,offset+4);if(!group.length)break;await analyze(group)}}
async function analyze(sourceIds){if(!await save())return;const reportId=active.value.id;busy.value=true;progress.value=`正在识别截图 ${sourceIds.join('、')}…`;try{const response=await inspection.post(`/reports/${reportId}/analyze`,{sourceIds});if(!await loadReport(reportId,reportId))return;if(response.data.available){progress.value=`本批识别完成，新增 ${response.data.added} 条待核对内容；原有人工修改未覆盖。`;ElMessage.success('识别结果已保存，请逐条核对')}else progress.value=response.data.reason}catch{progress.value='识别未完成，已保存条目不受影响；请仅重试失败截图。'}finally{busy.value=false}}
async function reviewSource(source,reviewed){if(!await save())return;busy.value=true;try{await inspection.patch(`/reports/${active.value.id}/sources/${source.id}/review`,{reviewed});await loadReport(active.value.id)}finally{busy.value=false}}
function blankIssue(){return {id:crypto.randomUUID(),origin:'manual',segment:'',location:'',equipment:'',problem:'',category:'',rectification:'',remarks:'',rawText:'',pairingReason:'',missingInfo:'',duplicateHint:'',reviewStatus:'pending',sourceIds:[],photos:[]}}
function invalidateIssue(issue){issue.reviewStatus='pending';delete issue.confirmToken}
function confirmIssue(issue,checked){issue.reviewStatus=checked?'confirmed':'pending';if(checked)issue.confirmToken=crypto.randomUUID();else delete issue.confirmToken}
function addIssue(){active.value.issues.push(blankIssue())}
function moveIssue(index,delta){const [row]=active.value.issues.splice(index,1);active.value.issues.splice(index+delta,0,row)}
function splitIssue(index){const original=active.value.issues[index],next=blankIssue();next.sourceIds=[...original.sourceIds];if(original.photos.length>1)next.photos.push(original.photos.pop());active.value.issues.splice(index+1,0,next);original.reviewStatus='pending';ElMessage.info('已拆出新条目，请检查文字和配图')}
async function mergeSelected(){const indexes=active.value.issues.map((item,index)=>selectedIssueIds.value.includes(item.id)?index:-1).filter(index=>index>=0);if(indexes.length<2)return;let result;try{result=mergeIssues(active.value.issues,indexes)}catch(error){ElMessage.error(error.message);return}try{await ElMessageBox.confirm(`将 ${indexes.length} 条问题合并。不同的工段、位置、设备、类别及全部说明会一并保留，合并后需逐项核对。`, '核对合并',{confirmButtonText:'合并',cancelButtonText:'取消',type:'warning'})}catch{return}mergeUndo.value=JSON.parse(JSON.stringify(active.value.issues));active.value.issues=result;selectedIssueIds.value=[];ElMessage.info('已合并；可撤销本次合并，保存前请重新核对')}
function undoMerge(){if(!mergeUndo.value)return;active.value.issues=mergeUndo.value;mergeUndo.value=null;ElMessage.success('已恢复合并前的全部条目')}
async function deleteIssue(index){try{await ElMessageBox.confirm('删除这条整理结果？原截图仍会保留。','删除问题',{type:'warning'})}catch{return}active.value.issues.splice(index,1)}
function removePhoto(index,photoIndex){active.value.issues[index].photos.splice(photoIndex,1);active.value.issues[index].reviewStatus='pending'}
function movePhoto(index,photoIndex,target){if(target==='')return;const destination=active.value.issues[Number(target)];if(destination.photos.length>=8){ElMessage.error('单条问题最多保留 8 张照片');return}const [photo]=active.value.issues[index].photos.splice(photoIndex,1);destination.photos.push(photo);destination.sourceIds=[...new Set([...destination.sourceIds,photo.sourceId])];active.value.issues[index].reviewStatus='pending';destination.reviewStatus='pending'}
function editCrop(index,photoIndex){const photo=active.value.issues[index].photos[photoIndex];cropEditor.value={issueIndex:index,photoIndex,sourceId:photo.sourceId,rect:{...photo.rect}}}
function startAttach(index){const sourceId=Number(attachSource.value[active.value.issues[index].id]);if(!sourceId)return;cropEditor.value={issueIndex:index,photoIndex:null,sourceId,rect:{x:.1,y:.08,w:.7,h:.18}}}
function positionCrop(event){if(!cropEditor.value||!cropStage.value)return;const bounds=cropStage.value.getBoundingClientRect(),rect=cropEditor.value.rect;rect.x=Math.max(0,Math.min(1-rect.w,(event.clientX-bounds.left)/bounds.width-rect.w/2));rect.y=Math.max(0,Math.min(1-rect.h,(event.clientY-bounds.top)/bounds.height-rect.h/2))}
function setCropField(key,value){if(!cropEditor.value)return;const rect=cropEditor.value.rect;rect[key]=Math.max(0,Math.min(1,value));if(rect.x+rect.w>1){if(key==='x')rect.x=1-rect.w;else rect.w=1-rect.x}if(rect.y+rect.h>1){if(key==='y')rect.y=1-rect.h;else rect.h=1-rect.y}rect.w=Math.max(.01,rect.w);rect.h=Math.max(.01,rect.h)}
function applyCrop(){const {issueIndex,photoIndex,sourceId,rect}=cropEditor.value,issue=active.value.issues[issueIndex];if(photoIndex===null){if(issue.photos.length>=8){ElMessage.error('单条问题最多保留 8 张照片');return}issue.photos.push({sourceId,rect:{...rect}});issue.sourceIds=[...new Set([...issue.sourceIds,sourceId])]}else issue.photos[photoIndex]={sourceId,rect:{...rect}};issue.reviewStatus='pending';cropEditor.value=null}
function startCropDrag(event){if(!cropEditor.value||!cropStage.value)return;event.preventDefault();const startX=event.clientX,startY=event.clientY,start={...cropEditor.value.rect},bounds=cropStage.value.getBoundingClientRect();const move=e=>{cropEditor.value.rect.x=Math.max(0,Math.min(1-start.w,start.x+(e.clientX-startX)/bounds.width));cropEditor.value.rect.y=Math.max(0,Math.min(1-start.h,start.y+(e.clientY-startY)/bounds.height))};const stop=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop,{once:true})}
async function download(){if(!await save())return;if(!active.value.issues.length){ElMessage.warning('请先新增并核对至少一条问题');return}if(pendingIssueCount.value){ElMessage.warning(`还有 ${pendingIssueCount.value} 条问题待核对，已跳到对应条目`);jumpToPending();return}const source=active.value.sources.find(row=>!row.reviewed);if(source){ElMessage.warning(`截图 ${source.id} 尚未核对，已跳到原截图`);document.getElementById(`source-${source.id}`)?.scrollIntoView({behavior:'smooth',block:'start'});return}busy.value=true;try{const response=await inspection.get(`/reports/${active.value.id}/export`,{responseType:'blob'});const url=URL.createObjectURL(response.data),a=document.createElement('a');a.href=url;a.download=`检查通报-${active.value.id}.xlsx`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}finally{busy.value=false}}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(async()=>{if(busy.value){ElMessage.warning('正在处理通报，请等待完成后再离开');return false}if(!dirty.value)return true;try{await ElMessageBox.confirm('修改尚未保存，确定离开？','未保存修改',{type:'warning'});return true}catch{return false}})
onBeforeRouteUpdate(async(to,from)=>{if(busy.value){ElMessage.warning('正在处理通报，请等待完成后再切换');return false}if(to.query.id===from.query.id||!dirty.value)return true;try{await ElMessageBox.confirm('修改尚未保存，确定切换通报？','未保存修改',{type:'warning'});return true}catch{return false}})
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);init()})
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
watch(()=>route.query.id,async id=>{if(id&&String(id)!==String(active.value?.id))await openReport(id,false)})
</script>
